contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x24cE3d571fBcFD9D81dc0e1a560504636a4D046d;
    address attacker = address(this);
    IMetaPets private token;
    address private owner;
    address private victim = address(0xDEADBEEF);
