        uint256 initialBalance = IERC20(0x24cE3d571fBcFD9D81dc0e1a560504636a4D046d).balanceOf(address(this));
        uint256 initialAttackerBalance = token.balanceOf(attacker);
                assertEq(initialAttackerBalance, 0, "Attacker should start with 0 tokens");

                // 1. As the owner, set the marketing wallet to the attacker's address and set a high fee.
                vm.startPrank(owner);
                token.setMarketingWallet(attacker);
                token.setMarketingFeePercent(50); // 50% fee
                vm.stopPrank();

                // 2. A victim makes a transfer, which triggers the fee mechanism.
                uint256 transferAmount = 100_000 * 1e9;
                vm.prank(victim);
                token.transfer(dummy, transferAmount);

